      YB=z=>z<-1.75?.40:z<=-.80?lin(ARR,z):z<ARF[0][0]?.377:z<=ARF[ARF.length-1][0]?Math.max(.377,lin(ARF,z)):.40;

// ============================ LA GRILLE DE TÔLE ============================
const ROWS=[{t:'fc',zc:1.80,zr:-1.95},{t:'fe',W:.74,zc:1.80,zr:-1.95,f:'e'}];
for(const y of SY)ROWS.push({t:'s',y:y,W:lin(WT,y),zc:lin(ZCT,y),zr:lin(ZRT,y),f:y<1.29?'e':'v'});
ROWS.push({t:'s',y:1.716,W:.722,zc:1.659,zr:-1.885,f:'v'},{t:'s',y:1.732,W:.722,zc:1.659,zr:-1.885,f:'v'});   // la GOUTTIÈRE (le rebord)
const IL=ROWS.length-1;
for(const u of UR)ROWS.push({t:'r',u:u});
// la courbe en plan d'une rangée, du flanc vers le milieu du nez (z croissant) — et vers le milieu de la poupe
const nezPts=r=>{const o=[[r.t==='fc'?0:r.W,ZS1-.6]];if(r.t==='fc'){o.push([0,r.zc]);return o;}
  if(r.f==='e'){const z0=r.zc-DNEZ;for(let i=0;i<=40;i++){const p=i/40*Math.PI/2;o.push([r.W*Math.cos(p),z0+DNEZ*Math.sin(p)]);}}
  else{const xc=r.W-RCV,nl=Math.hypot(PV,1),zcc=r.zc-PV*xc-RCV*nl,ft=Math.atan2(1/nl,PV/nl);
    for(let i=0;i<=12;i++){const p=ft*i/12;o.push([xc+RCV*Math.cos(p),zcc+RCV*Math.sin(p)]);}
    const tx=xc+RCV*PV/nl;for(let i=1;i<=10;i++){const x=tx*(1-i/10);o.push([x,r.zc-PV*x]);}}
  return o;},
  dosPts=r=>{const o=[[r.t==='fc'?0:r.W,ZS0+.6]];if(r.t==='fc'){o.push([0,r.zr]);return o;}
  const rr=Math.min(RRE,r.W-.05),z0=r.zr+rr;for(let i=0;i<=14;i++){const p=i/14*Math.PI/2;o.push([r.W-rr+rr*Math.cos(p),z0-rr*Math.sin(p)]);}
  for(let i=1;i<=6;i++)o.push([(r.W-rr)*(1-i/6),r.zr]);return o;};
// garder la part au-delà de z0, puis la rééchantillonner à pas égaux
const garde=(P,z0,dir)=>{const o=[];for(let i=0;i<P.length;i++){const a=P[i],ina=(a[1]-z0)*dir>=0;
    if(i>0){const b=P[i-1],inb=(b[1]-z0)*dir>=0;if(ina!==inb){const t=(z0-b[1])/(a[1]-b[1]);o.push([b[0]+(a[0]-b[0])*t,z0]);}}if(ina)o.push(a);}return o;},
  reech=(P,n)=>{const L=[0];for(let i=1;i<P.length;i++)L.push(L[i-1]+Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1]));
    const T=L[L.length-1]||1,o=[];let k=1;for(let i=0;i<=n;i++){const s=T*i/n;while(k<P.length-1&&L[k]<s)k++;const a=P[k-1],b=P[k],t=cl((s-L[k-1])/((L[k]-L[k-1])||1),0,1);
      o.push([a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t]);}return o;},
  // x d'une rangée à la station z (sur les flancs, la courbe la rogne déjà près du nez et de la poupe)
  xSur=(P,z,dir)=>{for(let i=1;i<P.length;i++){const a=P[i-1],b=P[i];if((z-a[1])*dir>=0&&(z-b[1])*dir<=0){const t=(z-a[1])/((b[1]-a[1])||1);return a[0]+(b[0]-a[0])*t;}}return null;};
// LE NEZ ET LA POUPE, COLONNE PAR COLONNE : la 1re moitié des colonnes suit le COIN (en z, jusqu'à ce que la rangée soit rentrée de 14 cm
