  const hw=TW/2,fx=hw-.018,J=lpKit({k:{g:'m',c:0x16171a},d:{g:'m',c:0x0e0f12},r:{g:GP,c:EP.c,f:0},c:{g:'c',c:0xe3e6ea}});
